#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# ── Config: the only place project-specific values live ───────────────────
# The wizard refuses to run while any value is empty or still a <placeholder>.
PRODUCT_NAME='<product name>'
INFISICAL_PROJECT_ID='<infisical project id>'
INFISICAL_DOMAIN='<https://app.infisical.com or the EU/self-hosted URL>'
INFISICAL_PATH='<folder of the product vars, e.g. /products/app>'
SRC_ENV='prod'                      # Infisical env the release vars are copied from
DST_ENV='dev'                       # Infisical env staging reads; never prod
RELEASE_TOKEN_NAME='<APP>_RELEASE_READ_TOKEN'
RELEASE_REPO_NAME='<APP>_RELEASE_REPOSITORY'
TEST_FLAG_NAME='TEST_SIGN_IN_ENABLED'
TEST_PASSWORD_NAME='TEST_SIGN_IN_PASSWORD'
SUPABASE_REF='<dev project ref>'
PROD_SUPABASE_REF='<prod project ref>'
STAGING_URL='<https://staging.example.com>'
PROD_URL='<https://www.example.com>'
TEST_SIGN_IN_PATH='/auth/test-sign-in?fixture='   # fixture name is appended
FREE_FIXTURE='free'; PRO_FIXTURE='pro'
FREE_EMAIL='<free-fixture@test.example.com>'
PRO_EMAIL='<pro-fixture@test.example.com>'
GRANT_CMD='<the staging-only grant command in this repo, e.g. pnpm test-account grant pro>'
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE=/dev/null   # nothing here is written to a .env; vars live in Infisical

fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; }

# refuse_production: every value set, and nothing points at production.
refuse_production() {
  local v bad=0
  for v in PRODUCT_NAME INFISICAL_PROJECT_ID INFISICAL_DOMAIN INFISICAL_PATH SRC_ENV DST_ENV \
           RELEASE_TOKEN_NAME RELEASE_REPO_NAME TEST_FLAG_NAME TEST_PASSWORD_NAME \
           SUPABASE_REF PROD_SUPABASE_REF STAGING_URL PROD_URL TEST_SIGN_IN_PATH \
           FREE_FIXTURE PRO_FIXTURE FREE_EMAIL PRO_EMAIL GRANT_CMD; do
    if [[ -z "${!v:-}" || "${!v}" == *"<"* ]]; then fail "$v is empty or still a placeholder"; bad=1; fi
  done
  (( bad )) && return 1
  if [[ ! "$DST_ENV" =~ ^(dev|development|staging|test|qa)$ || "$DST_ENV" == "$SRC_ENV" ]]; then
    fail "DST_ENV=$DST_ENV is not a test environment or equals SRC_ENV"; return 1; fi
  if [[ "$SUPABASE_REF" == "$PROD_SUPABASE_REF" || "$SUPABASE_REF" =~ (prod|live) ]]; then
    fail "SUPABASE_REF looks like production"; return 1; fi
  if [[ "$STAGING_URL" == "$PROD_URL" || ! "$STAGING_URL" =~ ^https://([^/]*[.-])?(staging|stage|dev|test|qa|sandbox|preview)(-[^/@.]*)?\.[^/@.]+\.[^/@]+(/|$) ]]; then
    fail "STAGING_URL is production or lacks a staging/dev/test label in its host"; return 1; fi
  return 0
}

is_uuid() { [[ "$1" =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ ]]; }

need() { command -v "$1" >/dev/null 2>&1 || { fail "missing tool: $1"; exit 1; }; }

# Infisical helpers. Values travel in pipes and a 0600 temp file, never in an
# argument, a log or the history. Swap inf_get and inf_put if the repo has a wrapper.
IA=(--projectId="$INFISICAL_PROJECT_ID" --domain="$INFISICAL_DOMAIN" --silent)
inf_get() { infisical secrets get "$2" --env="$1" --path="$INFISICAL_PATH" "${IA[@]}" --plain; }
# --plain exits 0 on a missing secret, so test the value, not the exit code.
inf_has() { local v; v=$(inf_get "$1" "$2") || { fail "cannot read $2 in $1"; exit 1; }; [[ -n "$v" ]]; }
# inf_put runs in a pipe subshell, so the parent owns the temp file and the trap.
SECRET_TMP=$(umask 077; mktemp)
inf_put() { # ENV NAME, value on stdin
  tr -d '\n' > "$SECRET_TMP"
  [[ -s "$SECRET_TMP" ]] || { fail "empty value for $2, nothing written"; return 1; }
  if infisical secrets set "$2=@$SECRET_TMP" --env="$1" --path="$INFISICAL_PATH" "${IA[@]}" >/dev/null; then
    : > "$SECRET_TMP"
    printf '  %s✓ set%s %s in %s\n' "$GREEN" "$RESET" "$2" "$1"
  else
    : > "$SECRET_TMP"; fail "could not set $2 in $1"; return 1
  fi
}
CLIP_USED=0
cleanup() { rm -f "$SECRET_TMP"; (( CLIP_USED )) && printf '' | pbcopy; return 0; }
trap cleanup EXIT

# status URL prints only the HTTP code; redirects are not followed.
status() { curl -sS -o /dev/null -w '%{http_code}' --max-time 20 "$1" 2>/dev/null || printf '000'; }
# probe URL prints the HTTP code, a space, then the absolute redirect target.
probe() { curl -sS -o /dev/null -w '%{http_code} %{redirect_url}' --max-time 20 "$1" 2>/dev/null || true; }

refuse_production || exit 1
if [[ "${1:-}" == "--check" ]]; then printf '  %s✓ config ok%s\n' "$GREEN" "$RESET"; exit 0; fi
[[ -t 0 ]] || { fail "this wizard needs a terminal; nothing was written (--check validates the config only)"; exit 1; }
need infisical; need openssl; need curl; need pbcopy

TOTAL_STAGES=5
banner "$PRODUCT_NAME: Mac test setup on staging"

# ── 1. Release vars, prod → dev ───────────────────────────────────────────
stage "Release read token and repository: $SRC_ENV → $DST_ENV"
say "Staging's Mac download route and update feed need these. Values are never shown."
for n in "$RELEASE_TOKEN_NAME" "$RELEASE_REPO_NAME"; do
  if ! inf_has "$SRC_ENV" "$n"; then fail "$n is missing in $SRC_ENV; release the Mac app first (coduo-release-mac-app)"; exit 1; fi
  if inf_has "$DST_ENV" "$n" && ! confirm "$n already exists in $DST_ENV. Overwrite?"; then note "kept $n"; continue; fi
  val=$(inf_get "$SRC_ENV" "$n") || { fail "cannot read $n in $SRC_ENV; nothing written"; exit 1; }
  [[ -n "$val" ]] || { fail "$n is empty in $SRC_ENV; nothing written"; exit 1; }
  printf '%s' "$val" | inf_put "$DST_ENV" "$n"
done
pause

# ── 2. Switch and password, straight into Infisical ───────────────────────
stage "Test sign-in switch and password"
say "Sets $TEST_FLAG_NAME=true and a random $TEST_PASSWORD_NAME in $DST_ENV. Nobody sees the password."
flag=$(inf_get "$DST_ENV" "$TEST_FLAG_NAME") || { fail "cannot read $TEST_FLAG_NAME in $DST_ENV"; exit 1; }
if [[ "$flag" == "true" ]]; then
  note "$TEST_FLAG_NAME is already true"
elif [[ -n "$flag" ]] && ! confirm "$TEST_FLAG_NAME exists and is not true. Overwrite with true?"; then
  note "kept $TEST_FLAG_NAME"
else
  printf 'true' | inf_put "$DST_ENV" "$TEST_FLAG_NAME"
fi
if inf_has "$DST_ENV" "$TEST_PASSWORD_NAME" \
   && ! confirm "$TEST_PASSWORD_NAME exists. Replace it? (Both fixture users must then be given the new one.)"; then
  note "kept $TEST_PASSWORD_NAME"
else
  openssl rand -base64 32 | inf_put "$DST_ENV" "$TEST_PASSWORD_NAME"
fi
pause

# ── 3. Fixture users in the dev Supabase project ──────────────────────────
stage "Create the two fixture users"
say "The password goes on your clipboard (never on screen) and is cleared at the end of this stage."
inf_has "$DST_ENV" "$TEST_PASSWORD_NAME" || { fail "$TEST_PASSWORD_NAME is missing in $DST_ENV"; exit 1; }
CLIP_USED=1
inf_get "$DST_ENV" "$TEST_PASSWORD_NAME" | pbcopy
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/auth/users"
step "Check the project ref in the URL is the DEV project: $SUPABASE_REF"
step "Authentication > Sign In / Providers > Email: switch Email on, then turn OFF \"Allow new users to sign up\", so only the fixtures can sign in. Save."
step "Back in Authentication > Users: Add user > Create new user. Email: $FREE_EMAIL. Paste the password. Tick Auto Confirm User. Create."
step "Repeat for $PRO_EMAIL, pasting the same password (still on the clipboard)."
step "If a user already exists and you replaced the password in stage 2, open the user, choose Reset password, and paste."
pause "Both users exist and show as confirmed? Press Enter."
printf '' | pbcopy; CLIP_USED=0
say "Clipboard cleared."

# ── 4. Pro user id, then hand the agent one command ───────────────────────
stage "Pro user id and the one step for the agent"
say "Open the pro user in the dashboard and copy its User UID (an id, not a secret)."
ask PRO_USER_ID "Pro user id:"
is_uuid "$PRO_USER_ID" || { fail "that is not a UUID"; exit 1; }
say "Give the agent this one instruction:"
printf '\n    %s%s %s %s%s\n\n' "$BOLD" "$GRANT_CMD" "$PRO_USER_ID" "$PRO_EMAIL" "$RESET"
note "It runs the repo's staging-only script, which refuses unless the database is the dev project."
pause "Done, or handed over? Press Enter."

# ── 5. Probe staging and production ───────────────────────────────────────
stage "Probe the test sign-in route"
say "Redeploy staging first so it sees the new values (the repo's deploy step; do not set vars in a provider dashboard)."
pause "Staging redeployed? Press Enter."
# The probe sends no password, so anyone who reaches staging can sign in as a
# fixture. The route's rule is in SKILL.md: never on in production, a fixed
# fixture allowlist, restricted staging access.
fails=0
app=${STAGING_URL#https://}; app=https://${app%%/*}
for f in "$FREE_FIXTURE:$FREE_EMAIL" "$PRO_FIXTURE:$PRO_EMAIL"; do
  read -r code target <<<"$(probe "$STAGING_URL$TEST_SIGN_IN_PATH${f%%:*}")"
  # A 3xx alone proves nothing: an access gate redirects too. Only the app's own origin counts.
  if [[ "$code" =~ ^3 && ( "$target" == "$app" || "$target" == "$app"/* ) ]]; then printf '  %s✓ PASS%s staging %s → %s\n' "$GREEN" "$RESET" "${f%%:*}" "$code"
  elif [[ "$code" =~ ^3 ]]; then printf '  %s✗ FAIL%s staging %s → %s to %s (not the app: an access gate stopped the probe, so nothing signed in)\n' "$RED" "$RESET" "${f%%:*}" "$code" "${target%%\?*}"; fails=1
  else printf '  %s✗ FAIL%s staging %s → %s (404: flag off or not redeployed; 401: user or password wrong, or a route hiding a 422; 422: email_provider_disabled, switch the Email provider on, stage 3)\n' "$RED" "$RESET" "${f%%:*}" "$code"; fails=1; fi
done
code=$(status "$PROD_URL${TEST_SIGN_IN_PATH}$FREE_FIXTURE")
if [[ "$code" == "404" ]]; then printf '  %s✓ PASS%s production → 404\n' "$GREEN" "$RESET"
else printf '  %s✗ FAIL%s production → %s (expected 404)\n' "$RED" "$RESET" "$code"; fails=1; fi
(( fails )) && exit 1
# ──────────────────────────────────────────────────────────────────────────

finish
